window.AUTH=window.AUTH||{};window.AUTH["17-1705"]={"d":"17-1705","id":"2018/17-1705","n":"PDR Network, LLC v. Carlton & Harris Chiropractic Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioners PDR Network, LLC, et al.","date":"2019-01-08","url":"https://www.supremecourt.gov/DocketPDF/17/17-1705/78749/20190108155908863_PDR%20Merits%20Brief.pdf","side":"pet","n":96},{"k":"respondent","label":"Brief of respondent Carlton & Harris Chiropractic, Inc.","date":"2019-02-07","url":"https://www.supremecourt.gov/DocketPDF/17/17-1705/87416/20190207123213257_Carlton%20%20Harris%20v.%20PDR%20Respondent%20Brief.pdf","side":"res","n":89},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-02-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-1705/88525/20190214193029314_17-1705bsacUnitedStates.pdf","side":"us","n":77},{"k":"reply","label":"Reply of petitioners PDR Network, LLC, et al.","date":"2019-03-11","url":"https://www.supremecourt.gov/DocketPDF/17/17-1705/91523/20190311124707158_2019.03.11%20PDR%20Reply%20in%20No.%2017-1705.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/588US1PP_final.pdf#page=9","tr":true,"items":[{"t":"case","label":"ACA Int’l v. FCC","cite":"885 F.3d 687","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/885/687/","by":{"0":"38","1":"1, 8, 35, 45"}},{"t":"case","label":"Adamo Wrecking Co. v. United States","cite":"434 U.S. 275","y":1978,"id":"1977/76-911","sc":1,"op":3,"ar":1,"sum":"The Clean Air Act authorizes the Administrator of the Environmental Protection Agency (EPA) to promulgate \"emission standards\" for hazardous air pollutants. The emission of an air pollutant in violation of an applicable emission standard is prohibited by § 112 (c) (1) (B), the knowing violation of which is made a criminal offense by § 113 (c) (1) (C). Section 307 (b) (1) provides that a petition for review of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 41","3":"16"}},{"t":"case","label":"Appalachian Power Co. v. EPA","cite":"208 F.3d 1015","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/208/1015/","by":{"0":"45"}},{"t":"case","label":"Ass’n of Flight Attendants-CWA v. Huerta","cite":"785 F.3d 710","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/785/710/","by":{"0":"48"}},{"t":"case","label":"AT&T Mobility LLC v. Concepcion","cite":"563 U.S. 333","y":2011,"id":"2010/09-893","sc":1,"sum":"The Court held the Federal Arbitration Act preempts state laws that \"stand as obstacles to the FAA's objectives.\"","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"0":"40","1":"42"}},{"t":"case","label":"Bais Yaakov of Spring Valley v. FCC","cite":"852 F.3d 1078","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1078/","ar":1,"sum":"Holding, in 2017, that the FCC lacked authority to issue TCPA regulation concerning solicited faxes and vacating a 2014 FCC order denying a petition for a declaratory ruling filed in 2010.","sumSrc":"brief:0","by":{"0":"37","1":"8, 20, 28–31"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"0":"42, 43","1":"43"}},{"t":"case","label":"Batterton v. Francis","cite":"432 U.S. 416","y":1977,"id":"1976/75-1181","sc":1,"op":1,"sum":"The regulation is a proper exercise of the Secretary's statutory authority and is reasonable.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","1":"46"}},{"t":"case","label":"Blonder-Tongue Labs., Inc. v. Univ. of Ill. Found.","cite":"402 U.S. 313","y":1971,"id":"1970/338","sc":1,"sum":"This Court's holding in Triplett v. Lowell, 297 U. S. 638, that a determination of patent invalidity is not res judicata against the patentee in subsequent litigation against a different defendant overruled to the extent that it forecloses an estoppel plea by one facing a charge of infringement of a patent that has once been declared invalid, and in this infringement suit where because of Triplett petitioner did not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37","1":"36"}},{"t":"case","label":"Bowen v. Mich. Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"op":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","2":"31"}},{"t":"case","label":"Bridgeview Health Care Ctr., Ltd. v. Clark","cite":"816 F.3d 935","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/816/935/","sum":"Noting that the TCPA has “become the means of targeting small businesses”.","sumSrc":"brief:0","by":{"0":"4, 38"}},{"t":"case","label":"Calderon v. Ashmus","cite":"523 U.S. 740","y":1998,"id":"1997/97-391","sc":1,"sum":"The Court held that \"this action for a declaratory judgment and injunctive relief is not a justiciable case within the meaning of Article III.\" \"If the class members file habeas petitions, and the State asserts Chapter 154, the members obviously can litigate California's compliance with Chapter 154 at that time.","sumSrc":"Oyez","by":{"0":"21","2":"20"}},{"t":"case","label":"CE Design, Ltd. v. Prism Bus. Media, Inc.","cite":"606 F.3d 443","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/606/443/","by":{"0":"20","1":"11–12, 16–18, 22–23","2":"3, 13"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Nat. Res. Def. Coun- cil, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":5,"ar":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"47","1":"3, 5, 17–19, 45","2":"6"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"op":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Page Chrysler Corp. v. EPA","cite":"600 F.2d 904","y":1979,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/600/904/","op":1,"by":{"0":"41"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"0":"43","1":"43"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"45","3":"19"}},{"t":"case","label":"Columbia Broad. Sys., Inc. v. United States","cite":"316 U.S. 407","y":1942,"id":"scdb/1941-063","sc":1,"sum":"1. To maintain a suit under § 402 (a) of the Federal Communications Act of 1934, and the Urgent Deficiencies Act of October 22, 1913, 38 Stat. 219, 220, the action of the Commission sought to be set aside must be an \"order,\" and the bill must state a cause of action in equity.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","1":"44","3":"20, 21"}},{"t":"case","label":"Council Tree Inv’rs, Inc. v. FCC","cite":"739 F.3d 544","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/544/","by":{"0":"25"}},{"t":"case","label":"Creative Montessori Learning Ctrs. v. Ash- ford Gear LLC","cite":"662 F.3d 913","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/662/913/","by":{"0":"4"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Decker v. Nw. Envtl. Def. Ctr.","cite":"568 U.S. 597","y":2013,"id":"2012/11-338","sc":1,"sum":"The Court found that based on the Clean Water Act, a permit is not necessary for storm water runoff because it is not associated with industrial activity.","sumSrc":"Oyez","by":{"0":"47","2":"28"}},{"t":"case","label":"Edwards v. Oportun, Inc.","cite":"193 F. Supp. 3d 1096","y":2016,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/193/1096/","by":{"0":"37","1":"35"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"op":4,"sum":"Petitioner accounting firm was retained to audit periodically a brokerage firm's books and records. Respondents, who were customers of the brokerage firm, invested in a securities scheme ultimately revealed as fraudulent and perpetrated by the firm's president and principal stockholder. After the fraud came to light, respondents filed an action for damages against petitioner under § 10 (b) of the Securities Exchange …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 32","1":"40"}},{"t":"case","label":"FCC v. ITT World Commc’ns, Inc.","cite":"466 U.S. 463","y":1984,"id":"1983/83-371","sc":1,"sum":"The Government in the Sunshine Act, 5 U. S. C. §552b(b), requires that \"meetings\" of a federal agency be open to the public. Section 552b(a)(2) defines a \"meeting\" as \"the deliberations of at least the number of individual agency members required to take action on behalf of the agency where such deliberations determine or result in the joint conduct or disposition of official agency business.\" Members of petitioner …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 31","1":"12, 28","2":"8, 16","3":"9"}},{"t":"case","label":"Flockhart v. Synchrony Bank","cite":"2017 WL 3276266","y":2017,"court":"N.D. Iowa Aug. 1","by":{"0":"38"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Functional Music, Inc. v. FCC","cite":"274 F.2d 543","y":1958,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/274/543/","ar":3,"by":{"0":"27, 29","1":"26, 37, 39–40","2":"30","3":"10, 13"}},{"t":"case","label":"Gage v. U.S. Atomic Energy Comm’n","cite":"479 F.2d 1214","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/479/1214/","by":{"0":"28","3":"10"}},{"t":"case","label":"Gray v. N.M. Military Inst.","cite":"249 F.2d 28","y":1957,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/249/28/","by":{"0":"21"}},{"t":"case","label":"Guevara v. Dorsey Labs.","cite":"845 F.2d 364","y":1988,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/845/364/","sum":"Noting that inclusion of warning in Physicians’ Desk Reference meant that defendant “unquestionably did warn of [a particular] hazard”.","sumSrc":"brief:0","by":{"0":"8"}},{"t":"case","label":"Page Hall v. Merck, Sharp & Dohme","cite":"774 F. Supp. 604","y":1991,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp./774/604/","sum":"Holding that information in Physicians’ Desk Reference was sufficient to warn physician of side effects for purposes of learned intermediary doctrine.","sumSrc":"brief:0","by":{"0":"8"}},{"t":"case","label":"Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"sum":"The phrase \"any other final action\" in § 307 (b) (1) is to be construed in accordance with its literal meaning so as to reach any action of the Administrator that is final, not just final actions of the Administrator similar to actions under the specifically enumerated provisions that precede the catchall phrase in the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"ICC v. Bhd. of Locomotive Eng’rs","cite":"482 U.S. 270","y":1987,"id":"1986/85-792","sc":1,"ar":1,"sum":"In October 1982, petitioner Interstate Commerce Commission (ICC or Commission) issued an order, which, inter alia, granted petitioner Missouri-Kansas-Texas Railroad Co. and another railroad the right to conduct operations using the tracks of a third, newly consolidated carrier. In April 1983, respondent Brotherhood of Locomotive Engineers (BLE) filed a \"Petition for Clarification\" asking the ICC to declare that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 36"}},{"t":"case","label":"Ill. Cent. Gulf R.R. v. ICC","cite":"720 F.2d 958","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/720/958/","by":{"0":"26, 27"}},{"t":"case","label":"Japan Whaling Ass’n v. Am. Cetacean Soc’y","cite":"478 U.S. 221","y":1986,"id":"1985/85-954","sc":1,"sum":"The International Convention for the Regulation of Whaling (ICRW) included a Schedule regulating whale harvesting practices of member nations (including the United States and Japan) and setting harvest limits for various whale species. It also established the International Whaling Commission (IWC) and authorized it to set harvest quotas. However, the IWC has no power to impose sanctions for quota violations, and any …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"40, 44","2":"31"}},{"t":"case","label":"Kawaauhau v. Geiger","cite":"523 U.S. 57","y":1998,"id":"1997/97-115","sc":1,"sum":"The Court held that \"debts arising from recklessly or negligently inflicted injuries do not fall within the compass of [section 523(a)(6)].\" Therefore, the debt is dischargeable.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Lathrop v. Uber Techs., Inc.","cite":"2016 WL 97511","y":2016,"court":"N.D. Cal. Jan. 8","by":{"0":"38","1":"35–36"}},{"t":"case","label":"Leyse v. Clear Channel Broad., Inc.","cite":"545 F. App’x 444","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/545/444/","by":{"0":"35"}},{"t":"case","label":"McDonnell v. United States","cite":"136 S. Ct. 2355","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Mims v. Arrow Fin. Servs., LLC","cite":"565 U.S. 368","y":2012,"id":"2011/10-1195","sc":1,"sum":"The Court held that the Telephone Consumer Protection Act does not strip federal courts of the ability to hear cases that would normally be brought in state courts.","sumSrc":"Oyez","by":{"0":"42","1":"45–46","2":"3"}},{"t":"case","label":"Mutual Pharm. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Nack v. Walburg","cite":"715 F.3d 680","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/715/680/","by":{"0":"20, 35","1":"11, 16, 20, 23, 28, 35","2":"13"}},{"t":"case","label":"Nat. Res. Def. Council v. Nuclear Regulatory Comm’n","cite":"666 F.2d 595","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/666/595/","sum":"Noting that a party who had the opportunity to seek direct review of a regulation cannot use a petition to repeal as a “back door procedural challenge[]” to challenge the procedures used to promulgate the original rule.","sumSrc":"brief:1","by":{"0":"25","1":"39","2":"28"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Nelson v. Sandoz Pharm. Corp.","cite":"288 F.3d 954","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/288/954/","by":{"0":"8"}},{"t":"case","label":"Page N.J. Dep’t of Envtl. Prot. & Energy v. Long Island Power Auth.","cite":"30 F.3d 403","y":1994,"court":"3d. Cir.","url":"https://www.courtlistener.com/c/F.3d/30/403/","by":{"0":"26"}},{"t":"case","label":"P.A.K. Transp., Inc. v. United States","cite":"613 F.2d 351","y":1980,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/613/351/","by":{"0":"26"}},{"t":"case","label":"Parklane Hosiery Co. v. Shore","cite":"439 U.S. 322","y":1979,"id":"1978/77-1305","sc":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"0":"45, 46, 47"}},{"t":"case","label":"Physicians Healthsource, Inc. v. Boehringer Ingelheim Pharm., Inc.","cite":"847 F.3d 92","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/847/92/","by":{"0":"26, 27","1":"13","3":"15"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"0":"43","1":"43"}},{"t":"case","label":"Port of Bos. Marine Terminal Ass’n v. Rederiaktiebolaget Transatlantic","cite":"400 U.S. 62","y":1970,"id":"1970/99","sc":1,"ar":3,"sum":"Petitioner Terminal Association, a maritime terminal operators conference. operating under an agreement approved by the Federal Maritime Commission (FMC), pursuant to §.15 of the Shipping Act, 1916, revised a tariff on file with the agency by shifting the incidence of a wharf demuri'age charge from consignees to carriers. When several carriers refused to pay the revised charge, which -had not previously been …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 30","1":"29","2":"passim","3":"9, 10, 15"}},{"t":"case","label":"Richards v. Jefferson Cty.","cite":"517 U.S. 793","y":1996,"id":"1995/95-386","sc":1,"sum":"Authored by Justice John Paul Stevens, the Court ruled that because Richards and others received neither notice of, nor sufficient representation in, the Bedingfield litigation, that adjudication, as a matter of federal due process, may not bind them and thus cannot bar them from challenging an allegedly unconstitutional deprivation of their property.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Ry. Mail Ass’n v. Corsi","cite":"326 U.S. 88","y":1945,"id":"scdb/1944-100","sc":1,"sum":"Section 43 of the New York Civil Rights Law forbids any \"labor organization\" to deny any person membership by reason of his race, color or creed, or to deny any member, by reason of race, color or creed, equal treatment in designation for employment, promotion or dismissal by any employer; other sections prescribe penalties and enforcement procedure. Appellant Railway Mail Association, an organization of regular and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","2":"20"}},{"t":"case","label":"Sandusky Wellness Ctr., LLC v. Medco Health Sols., Inc.","cite":"788 F.3d 218","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/788/218/","sum":"Holding that the “unambiguous terms” of the TCPA apply only to faxes with “commercial components” (internal quotation marks omitted).","sumSrc":"brief:0","by":{"0":"26, 47","1":"9–10"}},{"t":"case","label":"Schenebeck v. Sterling Drug, Inc.","cite":"423 F.2d 919","y":1970,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/423/919/","by":{"0":"8"}},{"t":"case","label":"SEC v. Alpine Secs. Corp.","cite":"308 F. Supp. 3d 775","y":2018,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/308/775/","by":{"0":"32","1":"40"}},{"t":"case","label":"Setser v. United States","cite":"566 U.S. 231","y":2012,"id":"2011/10-7387","sc":1,"sum":"The Court held that a federal judge has discretion to order a federal sentence to run consecutively or concurrently with an anticipated state sentence.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Page Shalala v. Guernsey Mem’l Hosp.","cite":"514 U.S. 87","y":1995,"id":"1994/93-1251","sc":1,"op":1,"sum":"After the refinancing of its bonded debt resulted in a \"defeasance\" loss for accounting purposes, respondent health care provider (hereinafter Hospital) determined that it was entitled to Medicare reimbursement for part of that loss. Although the Hospital contended that it should receive its full reimbursement in the year of the refinancing, the fiscal intermediary agreed with petitioner Secretary of Health and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Simmons v. ICC","cite":"716 F.2d 40","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/716/40/","by":{"0":"15, 25"}},{"t":"case","label":"St. Joseph Stock Yards Co. v. United States","cite":"298 U.S. 38","y":1936,"id":"scdb/1935-150","sc":1,"sum":"1. Past conditions of the business affected, during a reasonable period, as well as existing conditions, are properly to be considered by a rate-making authority in fixing rates for the future.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Telecomms. Research & Action Ctr. v. FCC","cite":"750 F.2d 70","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/750/70/","sum":"Describing FCC delays of two, four, and five years in resolving petitions.","sumSrc":"brief:0","by":{"0":"37","1":"12"}},{"t":"case","label":"Tenn. Pub. Serv. Comm’n v. ICC","cite":"921 F.2d 277","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/921/277/","by":{"0":"26"}},{"t":"case","label":"Texas v. United States","cite":"749 F.2d 1144","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/749/1144/","by":{"0":"27"}},{"t":"case","label":"Thomas v. Union Carbide Agric. Prods. Co.","cite":"473 U.S. 568","y":1985,"id":"1984/84-497","sc":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) requires manufacturers of pesticides, as a precondition for registering a pesticide, to submit research data to the Environmental Protection Agency (EPA) concerning the product's health, safety, and environmental effects, and authorizes EPA to use previously submitted data in considering an application for registration of a similar product by another …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Tri-State Motor Transit Co. v. ICC","cite":"739 F.2d 1373","y":1984,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/739/1373/","by":{"0":"27"}},{"t":"case","label":"U.S. Nat’l Bank of Or. v. Indep. Ins. Agents of Am., Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"United States v. Azmat","cite":"805 F.3d 1018","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/805/1018/","by":{"0":"8"}},{"t":"case","label":"United States v. O’Hagan","cite":"521 U.S. 642","y":1997,"id":"1996/96-842","sc":1,"op":2,"sum":"The Court ruled that a security-trader who fails to disclose personal profits gained from reliance on exclusive information is guilty of employing \"a deceptive device...in connection with the purchase of a security.\" The security-trader knowingly abuses the duty owed toward the source of information, whether the source is the company he works for or not.","sumSrc":"Oyez","by":{"0":"32","1":"40, 42","3":"18"}},{"t":"case","label":"United States v. Picciotto","cite":"875 F.2d 345","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/875/345/","sum":"Explaining that interpretive rules “merely restate existing duties, rather than creat[e] new duties”.","sumSrc":"brief:0","by":{"0":"48"}},{"t":"case","label":"United States v. Pitt-Des Moines, Inc.","cite":"970 F. Supp. 1346","y":1997,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./970/1346/","by":{"0":"32","1":"40"}},{"t":"case","label":"Viet. Veterans of Am. v. Sec’y of the Navy","cite":"843 F.2d 528","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/843/528/","by":{"0":"46"}},{"t":"case","label":"Weaver v. Fed. Motor Carrier Safety Admin.","cite":"744 F.3d 142","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/744/142/","ar":2,"by":{"0":"27"}},{"t":"case","label":"Page Whirlpool Corp. v. Marshall","cite":"445 U.S. 1","y":1980,"id":"1979/78-1870","sc":1,"op":1,"sum":"The regulation in question was promulgated by respondent in the valid exercise of his authority under the Act, and constitutes a permissible gloss on the Act, in light of the Act's language, structure, and legislative history.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"40"}},{"t":"case","label":"Wind River Mining Corp. v. United States","cite":"946 F.2d 710","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/946/710/","by":{"0":"27"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"op":17,"ar":17,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"43","2":"passim","3":"6, 7, 8, 13"}},{"t":"law","label":"AND REGULATIONS Administrative Orders Review Act, Pub. L. No. 81-901","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 102-243","url":"https://www.govinfo.gov/link/statute/105/2394","by":{"0":"3","2":"3"}},{"t":"law","label":"Pub. L. No. 109-21","url":"https://www.govinfo.gov/link/plaw/109/public/21","by":{"0":"4"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","subs":["(a)"],"stext":{"head":"§703. Form and venue of proceeding","paras":[[0,"The form of proceeding for judicial review is the special statutory review proceeding relevant to the subject matter in a court specified by statute or, in the absence or inadequacy thereof, any applicable form of legal action, including actions for declaratory judgments or writs of prohibitory or mandatory injunction or habeas corpus, in a court of competent jurisdiction. If no special statutory review proceeding is applicable, the action for judicial review may be brought against the United States, the agency by its official title, or the appropriate officer. Except to the extent that prior, adequate, and exclusive opportunity for judicial review is provided by law, agency action is subject to judicial review in civil or criminal proceedings for judicial enforcement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/703?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":3,"head":"§703. Form and venue of proceeding","tname":"Government Organization and Employees","by":{"0":"passim","1":"25, 28","2":"17","3":"1, 11"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","by":{"0":"32"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 655","url":"https://www.law.cornell.edu/uscode/text/29/655","subs":["(f)"],"stext":{"head":"§655. Standards","paras":[[0,"(a) Promulgation by Secretary of national consensus standards and established Federal standards; time for promulgation; conflicting standards"],[0,"Without regard to chapter 5 of title 5 or to the other subsections of this section, the Secretary shall, as soon as practicable during the period beginning with the effective date of this chapter and ending two years after such date, by rule promulgate as an occupational safety or health standard any national consensus standard, and any established Federal standard, unless he determines that the promulgation of such a standard would not result in improved safety or health for specifically designated employees. In the event of conflict among any such standards, the Secretary shall promulgate the standard which assures the greatest protection of the safety or health of the affected employees."],[0,"(b) Procedure for promulgation, modification, or revocation of standards"],[0,"The Secretary may by rule promulgate, modify, or revoke any occupational safety or health standard in the following manner:"],[0,"(1) Whenever the Secretary, upon the basis of information submitted to him in writing by an interested person, a representative of any organization of employers or employees, a nationally recognized standards-producing organization, the Secretary of Health and Human Services, the National Institute for Occupational Safety and Health, or a State or political subdivision, or on the basis of information developed by the Secretary or otherwise available to him, determines that a rule should be promulgated in order to serve the objectives of this chapter, the Secretary may request the recommendations of an advisory committee appointed under section 656 of this title. The Secretary shall provide such an advisory committee with any proposals of his own or of the Secretary of Health and Human Services, together with all pertinent factual information developed by the Secretary or the Secretary of Health and Human Services, or otherwise available, including the results of research, demonstrations, and experiments. An advisory committee shall submit to the Secretary its recommendations regarding the rule to be promulgated within ninety days from the date of its appointment or within such longer or shorter period as may be prescribed by the Secretary, but in no event for a period which is longer than two hundred and seventy days."],[0,"(2) The Secretary shall publish a proposed rule promulgating, modifying, or revoking an occupational safety or health standard in the Federal Register and shall afford interested persons a period of thirty days after publication to submit written data or comments. Where an advisory committee is appointed and the Secretary determines that a rule should be issued, he shall publish the proposed rule within sixty days after the submission of the advisory committee's recommendations or the expiration of the period prescribed by the Secretary for such submission."],[0,"(3) On or before the last day of the period provided for the submission of written data or comments under paragraph (2), any interested person may file with the Secretary written objections to the proposed rule, stating the grounds therefor and requesting a public hearing on such objections. Within thirty days after the last day for filing such objections, the Secretary shall publish in the Federal Register a notice specifying the occupational safety or health standard to which objections have been filed and a hearing requested, and specifying a time and place for such hearing."],[0,"(4) Within sixty days after the expiration of the period provided for the submission of written data or comments under paragraph (2), or within sixty days after the completion of any hearing held under paragraph (3), the Secretary shall issue a rule promulgating, modifying, or revoking an occupational safety or health standard or make a determination that a rule should not be issued. Such a rule may contain a provision delaying its effective date for such period (not in excess of ninety days) as the Secretary determines may be necessary to insure that affected employers and employees will be informed of the existence of the standard and of its terms and that employers affected are given an opportunity to familiarize themselves and their employees with the existence of the requirements of the standard."],[0,"(5) The Secretary, in promulgating standards dealing with toxic materials or harmful physical agents under this subsection, shall set the standard which most adequately assures, to the extent feasible, on the basis of the best available evidence, that no employee will suffer material impairment of health or functional capacity even if such employee has regular exposure to the hazard dealt with by such standard for the period of his working life. Development of standards under this subsection shall be based upon research, demonstrations, experiments, and such other information as may be appropriate. In addition to the attainment of the highest degree of health and safety protection for the employee, other considerations shall be the latest available scientific data in the field, the feasibility of the standards, and experience gained under this and other health and safety laws. Whenever practicable, the standard promulgated shall be expressed in terms of objective criteria and of the performance desired."],[0,"(6)(A) Any employer may apply to the Secretary for a temporary order granting a variance from a standard or any provision thereof promulgated under this section. Such temporary order shall be granted only if the employer files an application which meets the requirements of clause (B) and establishes that (i) he is unable to comply with a standard by its effective date because of unavailability of professional or technical personnel or of materials and equipment needed to come into compliance with the standard or because necessary construction or alteration of facilities cannot be completed by the effective date, (ii) he is taking all available steps to safeguard his employees against the hazards covered by the standard, and (iii) he has an effective program for coming into compliance with the standard as quickly as practicable. Any temporary order issued under this paragraph shall prescribe the practices, means, methods, operations, and processes which the employer must adopt and use while the order is in effect and state in detail his program for coming into compliance with the standard. Such a temporary order may be granted only after notice to employees and an opportunity for a hearing: Provided, That the Secretary may issue one interim order to be effective until a decision is made on the basis of the hearing. No temporary order may be in effect for longer than the period needed by the employer to achieve compliance with the standard or one year, whichever is shorter, except that such an order may be renewed not more than twice (I) so long as the requirements of this paragraph are met and (II) if an application for renewal is filed at least 90 days prior to the expiration date of the order. No interim renewal of an order may remain in effect for longer than 180 days."],[0,"(B) An application for a temporary order under this paragraph (6) shall contain:"],[1,"(i) a specification of the standard or portion thereof from which the employer seeks a variance,"],[1,"(ii) a representation by the employer, supported by representations from qualified persons having firsthand knowledge of the facts represented, that he is unable to comply with the standard or portion thereof and a detailed statement of the reasons therefor,"],[1,"(iii) a statement of the steps he has taken and will take (with specific dates) to protect employees against the hazard covered by the standard,"],[1,"(iv) a statement of when he expects to be able to comply with the standard and what steps he has taken and what steps he will take (with dates specified) to come into compliance with the standard, and"],[1,"(v) a certification that he has informed his employees of the application by giving a copy thereof to their authorized representative, posting a statement giving a summary of the application and specifying where a copy may be examined at the place or places where notices to employees are normally posted, and by other appropriate means."],[0,"A description of how employees have been informed shall be contained in the certification. The information to employees shall also inform them of their right to petition the Secretary for a hearing."],[0,"(C) The Secretary is authorized to grant a variance from any standard or portion thereof whenever he determines, or the Secretary of Health and Human Services certifies, that such variance is necessary to permit an employer to participate in an experiment approved by him or the Secretary of Health and Human Services designed to demonstrate or validate new and improved techniques to safeguard the health or safety of workers."],[0,"(7) Any standard promulgated under this subsection shall prescribe the use of labels or other appropriate forms of warning as are necessary to insure that employees are apprised of all hazards to which they are exposed, relevant symptoms and appropriate emergency treatment, and proper conditions and precautions of safe use or exposure. Where appropriate, such standard shall also prescribe suitable protective equipment and control or technological procedures to be used in connection with such hazards and shall provide for monitoring or measuring employee exposure at such locations and intervals, and in such manner as may be necessary for the protection of employees. In addition, where appropriate, any such standard shall prescribe the type and frequency of medical examinations or other tests which shall be made available, by the employer or at his cost, to employees exposed to such hazards in order to most effectively determine whether the health of such employees is adversely affected by such exposure. In the event such medical examinations are in the nature of research, as determined by the Secretary of Health and Human Services, such examinations may be furnished at the expense of the Secretary of Health and Human Services. The results of such examinations or tests shall be furnished only to the Secretary or the Secretary of Health and Human Services, and, at the request of the employee, to his physician. The Secretary, in consultation with the Secretary of Health and Human Services, may by rule promulgated pursuant to section 553 of title 5, make appropriate modifications in the foregoing requirements relating to the use of labels or other forms of warning, monitoring or measuring, and medical examinations, as may be warranted by experience, information, or medical or technological developments acquired subsequent to the promulgation of the relevant standard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/655?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§655. Standards","tname":"Labor","by":{"0":"31","1":"40","3":"18"}},{"t":"usc","label":"33 U.S.C. § 1369","url":"https://www.law.cornell.edu/uscode/text/33/1369","subs":["(b)","(b)(2)"],"stext":{"head":"§1369. Administrative procedure and judicial review","paras":[[0,"(a) Subpenas"],[0,"(1) For purposes of obtaining information under section 1315 of this title, or carrying out section 1367(e) of this title, the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for effluent data, upon a showing satisfactory to the Administrator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subsection, the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator, to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(2) The district courts of the United States are authorized, upon application by the Administrator, to issue subpenas for attendance and testimony of witnesses and the production of relevant papers, books, and documents, for purposes of obtaining information under sections 1314(b) and (c) of this title. Any papers, books, documents, or other information or part thereof, obtained by reason of such a subpena shall be subject to the same requirements as are provided in paragraph (1) of this subsection."],[0,"(b) Review of Administrator's actions; selection of court; fees"],[0,"(1) Review of the Administrator's action (A) in promulgating any standard of performance under section 1316 of this title, (B) in making any determination pursuant to section 1316(b)(1)(C) of this title, (C) in promulgating any effluent standard, prohibition, or pretreatment standard under section 1317 of this title, (D) in making any determination as to a State permit program submitted under section 1342(b) of this title, (E) in approving or promulgating any effluent limitation or other limitation under section 1311, 1312, 1316, or 1345 of this title, (F) in issuing or denying any permit under section 1342 of this title, and (G) in promulgating any individual control strategy under section 1314(l) of this title, may be had by any interested person in the Circuit Court of Appeals of the United States for the Federal judicial district in which such person resides or transacts business which is directly affected by such action upon application by such person. Any such application shall be made within 120 days from the date of such determination, approval, promulgation, issuance or denial, or after such date only if such application is based solely on grounds which arose after such 120th day."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) of this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement."],[0,"(3) Award of fees.—In any judicial proceeding under this subsection, the court may award costs of litigation (including reasonable attorney and expert witness fees) to any prevailing or substantially prevailing party whenever it determines that such award is appropriate."],[0,"(4) Discharges incidental to normal operation of vessels.—"],[1,"(A) In general.—Except as provided in subparagraph (B), any interested person may file a petition for review of a final agency action under section 1322(p) of this title of the Administrator or the Secretary of the department in which the Coast Guard is operating in accordance with the requirements of this subsection."],[1,"(B) Venue exception.—Subject to section 1322(p)(7)(C)(v) of this title, a petition for review of a final agency action under section 1322(p) of this title of the Administrator or the Secretary of the department in which the Coast Guard is operating may be filed only in the United States Court of Appeals for the District of Columbia Circuit."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding brought under subsection (b) of this section in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1369?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1369. Administrative procedure and judicial review","tname":"Navigation and Navigable Waters","by":{"0":"34","2":"23","3":"1"}},{"t":"usc","label":"42 U.S.C. § 5841","url":"https://www.law.cornell.edu/uscode/text/42/5841","subs":["(f)"],"stext":{"head":"§5841. Establishment and transfers","paras":[[0,"(a) Composition; Chairman; Acting Chairman; quorum; official spokesman; seal; functions of Chairman and Commission"],[0,"(1) There is established an independent regulatory commission to be known as the Nuclear Regulatory Commission which shall be composed of five members, each of whom shall be a citizen of the United States. The President shall designate one member of the Commission as Chairman thereof to serve as such during the pleasure of the President. The Chairman may from time to time designate any other member of the Commission as Acting Chairman to act in the place and stead of the Chairman during his absence. The Chairman (or the Acting Chairman in the absence of the Chairman) shall preside at all meetings of the Commission and a quorum for the transaction of business shall consist of at least three members present. Each member of the Commission, including the Chairman, shall have equal responsibility and authority in all decisions and actions of the Commission, shall have full access to all information relating to the performance of his duties or responsibilities, and shall have one vote. Action of the Commission shall be determined by a majority vote of the members present. The Chairman (or Acting Chairman in the absence of the Chairman) shall be the official spokesman of the Commission in its relations with the Congress, Government agencies, persons, or the public, and, on behalf of the Commission, shall see to the faithful execution of the policies and decisions of the Commission, and shall report thereon to the Commission from time to time or as the Commission may direct. The Commission shall have an official seal which shall be judicially noticed."],[0,"(2) The Chairman of the Commission shall be the principal executive officer of the Commission, and he shall exercise all of the executive and administrative functions of the Commission, including functions of the Commission with respect to (a) the appointment and supervision of personnel employed under the Commission (other than personnel employed regularly and full time in the immediate offices of commissioners other than the Chairman, and except as otherwise provided in this chapter), (b) the distribution of business among such personnel and among administrative units of the Commission, and (c) the use and expenditure of funds."],[0,"(3) In carrying out any of his functions under the provisions of this section the Chairman shall be governed by general policies of the Commission and by such regulatory decisions, findings, and determinations as the Commission may by law be authorized to make."],[0,"(4) The appointment by the Chairman of the heads of major administrative units under the Commission shall be subject to the approval of the Commission."],[0,"(5) There are hereby reserved to the Commission its functions with respect to revising budget estimates and with respect to determining upon the distribution of appropriated funds according to major programs and purposes."],[0,"(b) Appointment of members"],[0,"(1) Members of the Commission shall be appointed by the President, by and with the advice and consent of the Senate."],[0,"(2) Appointments of members pursuant to this subsection shall be made in such a manner that not more than three members of the Commission shall be members of the same political party."],[0,"(c) Term of office"],[0,"Each member shall serve for a term of five years, each such term to commence on July 1, except that of the five members first appointed to the Commission, one shall serve for one year, one for two years, one for three years, one for four years, and one for five years, to be designated by the President at the time of appointment; and except that any member appointed to fill a vacancy occurring prior to the expiration of the term for which his predecessor was appointed, shall be appointed for the remainder of such term. For the purpose of determining the expiration date of the terms of office of the five members first appointed to the Nuclear Regulatory Commission, each such term shall be deemed to have begun July 1, 1975."],[0,"(d) Submission of appointments to Senate"],[0,"Such initial appointments shall be submitted to the Senate within sixty days of October 11, 1974. Any individual who is serving as a member of the Atomic Energy Commission on October 11, 1974, and who may be appointed by the President to the Commission, shall be appointed for a term designated by the President, but which term shall terminate not later than the end of his present term as a member of the Atomic Energy Commission, without regard to the requirements of subsection (b)(2) of this section. Any subsequent appointment of such individuals shall be subject to the provisions of this section."],[0,"(e) Removal of members; prohibition against engagement in business or other employment"],[0,"Any member of the Commission may be removed by the President for inefficiency, neglect of duty, or malfeasance in office. No member of the Commission shall engage in any business, vocation, or employment other than that of serving as a member of the Commission."],[0,"(f) Transfer of licensing and regulatory functions of Atomic Energy Commission"],[0,"There are hereby transferred to the Commission all the licensing and related regulatory functions of the Atomic Energy Commission, the Chairman and members of the Commission, the General Counsel, and other officers and components of the Commission—which functions officers, components, and personnel are excepted from the transfer to the Administrator by section 5814(c) of this title."],[0,"(g) Additional transfers"],[0,"In addition to other functions and personnel transferred to the Commission, there are also transferred to the Commission—"],[1,"(1) the functions of the Atomic Safety and Licensing Board Panel and the Atomic Safety and Licensing Appeal Board;"],[1,"(2) such personnel as the Director of the Office of Management and Budget determines are necessary for exercising responsibilities under section 5845 of this title, relating to, research, for the purpose of confirmatory assessment relating to licensing and other regulation under the provisions of the Atomic Energy Act of 1954, as amended [42 U.S.C. 2011 et seq.], and of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/5841?type=usc&year=mostrecent&link-type=html"},"head":"§5841. Establishment and transfers","tname":"The Public Health and Welfare","by":{"0":"7","2":"2"}},{"t":"usc","label":"47 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/47/227","subs":["(a)","(a)(5)","(b)(1)(C)","(b)(1)(C)(i)","(b)(1)(C)(ii)","(b)(1)(C)(iii)","(b)(2)","(b)(3)","(c)(5)"],"stext":{"head":"§227. Restrictions on use of telephone equipment","paras":[[0,"(a) Definitions"],[0,"As used in this section—"],[1,"(1) The term \"automatic telephone dialing system\" means equipment which has the capacity—"],[2,"(A) to store or produce telephone numbers to be called, using a random or sequential number generator; and"],[2,"(B) to dial such numbers."],[1,"(2) The term \"established business relationship\", for purposes only of subsection (b)(1)(C)(i), shall have the meaning given the term in section 64.1200 of title 47, Code of Federal Regulations, as in effect on January 1, 2003, except that—"],[2,"(A) such term shall include a relationship between a person or entity and a business subscriber subject to the same terms applicable under such section to a relationship between a person or entity and a residential subscriber; and"],[2,"(B) an established business relationship shall be subject to any time limitation established pursuant to paragraph (2)(G)).1"],[1,"(3) The term \"telephone facsimile machine\" means equipment which has the capacity (A) to transcribe text or images, or both, from paper into an electronic signal and to transmit that signal over a regular telephone line, or (B) to transcribe text or images (or both) from an electronic signal received over a regular telephone line onto paper."],[1,"(4) The term \"telephone solicitation\" means the initiation of a telephone call or message for the purpose of encouraging the purchase or rental of, or investment in, property, goods, or services, which is transmitted to any person, but such term does not include a call or message (A) to any person with that person's prior express invitation or permission, (B) to any person with whom the caller has an established business relationship, or (C) by a tax exempt nonprofit organization."],[1,"(5) The term \"unsolicited advertisement\" means any material advertising the commercial availability or quality of any property, goods, or services which is transmitted to any person without that person's prior express invitation or permission, in writing or otherwise."],[0,"(b) Restrictions on use of automated telephone equipment"],[0,"(1) Prohibitions"],[1,"It shall be unlawful for any person within the United States, or any person outside the United States if the recipient is within the United States—"],[2,"(A) to make any call (other than a call made for emergency purposes or made with the prior express consent of the called party) using any automatic telephone dialing system or an artificial or prerecorded voice—"],[3,"(i) to any emergency telephone line (including any \"911\" line and any emergency line of a hospital, medical physician or service office, health care facility, poison control center, or fire protection or law enforcement agency);"],[3,"(ii) to the telephone line of any guest room or patient room of a hospital, health care facility, elderly home, or similar establishment; or"],[3,"(iii) to any telephone number assigned to a paging service, cellular telephone service, specialized mobile radio service, or other radio common carrier service, or any service for which the called party is charged for the call, unless such call is made solely to collect a debt owed to or guaranteed by the United States;"],[2,"(B) to initiate any telephone call to any residential telephone line using an artificial or prerecorded voice to deliver a message without the prior express consent of the called party, unless the call is initiated for emergency purposes, is made solely pursuant to the collection of a debt owed to or guaranteed by the United States, or is exempted by rule or order by the Commission under paragraph (2)(B);"],[2,"(C) to use any telephone facsimile machine, computer, or other device to send, to a telephone facsimile machine, an unsolicited advertisement, unless—"],[3,"(i) the unsolicited advertisement is from a sender with an established business relationship with the recipient;"],[3,"(ii) the sender obtained the number of the telephone facsimile machine through—"],[4,"(I) the voluntary communication of such number, within the context of such established business relationship, from the recipient of the unsolicited advertisement, or"],[4,"(II) a directory, advertisement, or site on the Internet to which the recipient voluntarily agreed to make available its facsimile number for public distribution,"],[0,"except that this clause shall not apply in the case of an unsolicited advertisement that is sent based on an established business relationship with the recipient that was in existence before July 9, 2005, if the sender possessed the facsimile machine number of the recipient before July 9, 2005; and"],[3,"(iii) the unsolicited advertisement contains a notice meeting the requirements under paragraph (2)(D),"],[2,"except that the exception under clauses (i) and (ii) shall not apply with respect to an unsolicited advertisement sent to a telephone facsimile machine by a sender to whom a request has been made not to send future unsolicited advertisements to such telephone facsimile machine that complies with the requirements under paragraph (2)(E); or"],[2,"(D) to use an automatic telephone dialing system in such a way that two or more telephone lines of a multi-line business are engaged simultaneously."],[0,"(2) Regulations; exemptions and other provisions"],[1,"The Commission shall prescribe regulations to implement the requirements of this subsection. In implementing the requirements of this subsection, the Commission—"],[2,"(A) shall consider prescribing regulations to allow businesses to avoid receiving calls made using an artificial or prerecorded voice to which they have not given their prior express consent;"],[2,"(B) may, by rule or order, exempt from the requirements of paragraph (1)(B) of this subsection, subject to such conditions as the Commission may prescribe—"],[3,"(i) calls that are not made for a commercial purpose; and"],[3,"(ii) such classes or categories of calls made for commercial purposes as the Commission determines—"],[4,"(I) will not adversely affect the privacy rights that this section is intended to protect; and"],[4,"(II) do not include the transmission of any unsolicited advertisement;"],[2,"(C) may, by rule or order, exempt from the requirements of paragraph (1)(A)(iii) of this subsection calls to a telephone number assigned to a cellular telephone service that are not charged to the called party, subject to such conditions as the Commission may prescribe as necessary in the interest of the privacy rights this section is intended to protect;"],[2,"(D) shall provide that a notice contained in an unsolicited advertisement complies with the requirements under this subparagraph only if—"],[3,"(i) the notice is clear and conspicuous and on the first page of the unsolicited advertisement;"],[3,"(ii) the notice states that the recipient may make a request to the sender of the unsolicited advertisement not to send any future unsolicited advertisements to a telephone facsimile machine or machines and that failure to comply, within the shortest reasonable time, as determined by the Commission, with such a request meeting the requirements under subparagraph (E) is unlawful;"],[3,"(iii) the notice sets forth the requirements for a request under subparagraph (E);"],[3,"(iv) the notice includes—"],[4,"(I) a domestic contact telephone and facsimile machine number for the recipient to transmit such a request to the sender; and"],[4,"(II) a cost-free mechanism for a recipient to transmit a request pursuant to such notice to the sender of the unsolicited advertisement; the Commission shall by rule require the sender to provide such a mechanism and may, in the discretion of the Commission and subject to such conditions as the Commission may prescribe, exempt certain classes of small business senders, but only if the Commission determines that the costs to such class are unduly burdensome given the revenues generated by such small businesses;"],[3,"(v) the telephone and facsimile machine numbers and the cost-free mechanism set forth pursuant to clause (iv) permit an individual or business to make such a request at any time on any day of the week; and"],[3,"(vi) the notice complies with the requirements of subsection (d);"],[2,"(E) shall provide, by rule, that a request not to send future unsolicited advertisements to a telephone facsimile machine complies with the requirements under this subparagraph only if—"],[3,"(i) the request identifies the telephone number or numbers of the telephone facsimile machine or machines to which the request relates;"],[3,"(ii) the request is made to the telephone or facsimile number of the sender of such an unsolicited advertisement provided pursuant to subparagraph (D)(iv) or by any other method of communication as determined by the Commission; and"],[3,"(iii) the person making the request has not, subsequent to such request, provided express invitation or permission to the sender, in writing or otherwise, to send such advertisements to such person at such telephone facsimile machine;"],[2,"(F) may, in the discretion of the Commission and subject to such conditions as the Commission may prescribe, allow professional or trade associations that are tax-exempt nonprofit organizations to send unsolicited advertisements to their members in furtherance of the association's tax-exempt purpose that do not contain the notice required by paragraph (1)(C)(iii), except that the Commission may take action under this subparagraph only—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/227?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§227. Restrictions on use of telephone equipment","tname":"Telecommunications","by":{"0":"1, 4, 49","1":"2, 12, 13, 1, 30, 14, 14, 14, 45, 1","2":"3, 3, 3, 3, 3"}},{"t":"reg","label":"47 C.F.R. § 1.104","url":"https://www.ecfr.gov/current/title-47/section-1.104","subs":["(b)"],"by":{"0":"36"}},{"t":"reg","label":"71 Fed. Reg. 25,967","url":"https://www.govinfo.gov/link/fr/71/25967","by":{"0":"5","2":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(f)"],"by":{"0":"38"}},{"t":"case","label":"Adarand Constructors, Inc. v. Mineta","cite":"534 U.S. 103","y":2001,"id":"2001/00-730","sc":1,"sum":"After Adarand asserted that it was only challenging the rules pertaining to the direct procurement of DOT funds for highway construction on federal lands rather than any part of the DOT's DBE program as it pertained to state and local procurement, the Court concluded that the posture of the case had changed.","sumSrc":"Oyez","by":{"1":"7, 10"}},{"t":"case","label":"Bebo v. SEC","cite":"799 F.3d 765","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/799/765/","by":{"1":"41"}},{"t":"case","label":"Brodsky v. HumanaDental Ins. Co.","cite":"910 F.3d 285","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/910/285/","by":{"1":"31"}},{"t":"case","label":"Campbell-Ewald Co. v. Gomez","cite":"136 S. Ct. 663","y":2016,"id":"2015/14-857","sc":1,"sum":"The Court held that an unaccepted settlement offer does not make a plaintiff’s claim moot, and a federal contractor does not have derivative sovereign liability from a suit under the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"1":"26, 35, 46"}},{"t":"case","label":"Carlton & Harris Chiropractic, Inc. v. PDR Network, LLC","cite":"883 F.3d 459","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/459/","op":4,"by":{"1":"4"}},{"t":"case","label":"Comprehensive Health Care Sys. Of the Palm Beaches, Inc. v. M3 USA Corp.","cite":"2017 WL 4868185","y":2017,"court":"S.D. Fla. Oct. 6","op":1,"by":{"1":"35"}},{"t":"case","label":"Degnen v. Dental Fix RX, LLC","cite":"2016 WL 4158888","y":2016,"court":"E.D. Mo. Aug. 5","by":{"1":"35"}},{"t":"case","label":"Dixon v. United States","cite":"381 U.S. 68","y":1965,"id":"1964/486","sc":1,"sum":"A partnership to which petitioners belong, in 1952 bought short-term noninterest-bearing notes at discounts. The purchases were assertedly made in reliance on the published acquiescence of the Commissioner of Internal Revenue in Caulkins v. Commissioner. I T. C. 656, aff'd 144 F. 2d 482, where the Tax Court had allowed capital gains treatment of the full amount a taxpayer had received on an \"Accumulative Installment …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Edison Elec. Inst. v. ICC","cite":"969 F.2d 1221","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/969/1221/","by":{"1":"27"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Holtzman v. Turza","cite":"728 F.3d 682","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/728/682/","by":{"1":"9–10"}},{"t":"case","label":"Chicago & N.W. Transp. Co. v. Kalo Brick & Tile Co.","cite":"450 U.S. 311","y":1981,"id":"1980/79-1336","sc":1,"sum":"The Interstate Commerce Act precludes a shipper from pressing a state-court action for damages against a regulated rail carrier when, as here, the ICC, in approving the carrier's application for abandonment, reaches the merits of the matters the shipper seeks to raise in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24–25"}},{"t":"case","label":"JEM Broad. Co. v. FCC","cite":"22 F.3d 320","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/22/320/","by":{"1":"39"}},{"t":"case","label":"Leyse v. Clear Channel Broad., Inc.","cite":"697 F.3d 360","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/360/","by":{"1":"11, 21"}},{"t":"case","label":"Leyse v. Clear Channel Broad., Inc., 545 Fed. App’x 444 (6th Cir. 2013) 11, 16, 21-23, 45 Lockerty v. Phillips","cite":"319 U.S. 182","y":1943,"id":"scdb/1942-149","sc":1,"sum":"1. The Emergency Price Control Act of 1942 sets up a procedure whereby any person subject to any regulation or order promulgated under the Act may on \"protest\" of the regulation or order secure its review by the Administrator; and, if the protest is denied, the Act confers on the Emergency Court (and on the Supreme Court upon review of decisions of the Emergency Court) equity jurisdicLOCKERTY v. PHILLIPS. Counsel …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12, 43"}},{"t":"case","label":"Mais v. Gulf Coast Collection Bureau, Inc.","cite":"944 F. Supp. 2d 1226","y":2013,"court":"S.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/944/1226/","by":{"1":"18"}},{"t":"case","label":"Mais v. Gulf Coast Collection Bureau, Inc.","cite":"768 F.3d 1110","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/1110/","by":{"1":"11, 16, 18–19, 23","2":"12"}},{"t":"case","label":"Manhattan Gen. Equip. v. Comm’r of Internal Revenue","cite":"297 U.S. 129","y":1935,"id":"scdb/1935-080","sc":1,"sum":"1. A loss resulting from the sale in 1926 of securities in respect of which a distribution pursuant to a plan of reorganization had been made, held properly determined, for the purpose of computing income tax under the Revenue Act of 1926, by the method prescribed by Art. 1599 of Treasury Regulations 65, as amended April 3, 1928, rather than by the original regulation promulgated August 28, 1926, where the effect of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36–37"}},{"t":"case","label":"Martinez v. United States","cite":"333 F.3d 1295","y":2003,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/333/1295/","by":{"1":"27"}},{"t":"case","label":"Mata v. Lynch","cite":"135 S. Ct. 2150","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2150/","sc":1,"by":{"1":"24"}},{"t":"case","label":"MedImmune, Inc. v. Genentech, Inc.","cite":"549 U.S. 118","y":2007,"id":"2006/05-608","sc":1,"sum":"The Court reversed the Federal Circuit and ruled for MedImmune.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Murphy v. DCI Biologicals Orlando, LLC","cite":"797 F.3d 1302","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/797/1302/","by":{"1":"19"}},{"t":"case","label":"Nack v. Walburg","cite":"2011 WL 310249","y":2011,"court":"E.D. Mo. Jan. 28","by":{"1":"19–20"}},{"t":"case","label":"Nack v. Walburg","cite":"2013 WL 4860104","y":2013,"court":"E.D. Mo. Sept. 12","by":{"1":"28–29"}},{"t":"case","label":"NLRB Union v. Fed. Labor Relations Auth.","cite":"834 F.2d 191","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/834/191/","by":{"1":"37–39, 40"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"136 S. Ct. 390","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"1":"8, 22, 26, 44"}},{"t":"case","label":"Sable Commc’ns of Cal., Inc. v. FCC","cite":"827 F.2d 640","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/827/640/","by":{"1":"27"}},{"t":"case","label":"Sandusky Wellness Ctr., LLC v. ASD Specialty Healthcare, Inc.","cite":"863 F.3d 460","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/460/","by":{"1":"31"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"sum":"Petitioner mine operator's nonunion work force designated two employees of the United Mine Workers of America (UMWA) to serve as miners' representatives under 30 U. S. C. §813(f). Claiming that the designations compromised its rights under the National Labor Relations Act (NLRA), petitioner refused to post information about the representatives as required by a regulation issued by the Department of Labor's Mine …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41–42","2":"31"}},{"t":"case","label":"Town of Sanford v. United States","cite":"140 F.3d 20","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/140/20/","by":{"1":"9, 27"}},{"t":"case","label":"True Health Chiropractic, Inc. v. McKesson Corp.","cite":"896 F.3d 923","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/896/923/","by":{"1":"31"}},{"t":"case","label":"United States v. Int’l Bus. Machines Corp.","cite":"517 U.S. 843","y":1996,"id":"1995/95-591","sc":1,"sum":"Announced by Justice Clarence Thomas, the Court ruled the tax did violate the Export Clause and was therefore unconstitutional.","sumSrc":"Oyez","by":{"1":"10"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Vonage Holdings Corp. v. Minnesota PUC","cite":"394 F.3d 568","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/394/568/","sum":"Holding “[n]o collateral attacks on the FCC Order are permitted” in private litigation, since “[t]he case before us is not a Hobbs Act petition for review.”.","sumSrc":"brief:1","by":{"1":"23"}},{"t":"case","label":"Whitney Nat’l Bank in Jefferson Parish v. Bank of New Orleans & Trust Co.","cite":"379 U.S. 411","y":1965,"id":"1964/26","sc":1,"sum":"A New Orleans-based national bank, desiring to expand but prohibited from operating branches beyond its home parish, formed a holding company which in turn organized a new national bank to operate in an adjoining parish. Pursuant to the Bank Holding Company Act of 1956, the Federal Reserve Board (FRB), after receiving favorable advice from the Comptroller of the Currency (Comptroller), held hearings on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41","3":"18"}},{"t":"case","label":"Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"usc","label":"5 U.S.C. § 7123","url":"https://www.law.cornell.edu/uscode/text/5/7123","subs":["(a)"],"by":{"1":"37"}},{"t":"usc","label":"8 U.S.C. § 252","url":"https://www.law.cornell.edu/uscode/text/8/252","subs":["(a)(1)"],"by":{"1":"24"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(a)"],"by":{"1":"36"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(b)(3)(B)"],"by":{"1":"36"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(a)","(a)(1)","(b)","(b)(1)"],"stext":{"head":"§78y. Court review of orders and rules","paras":[[0,"(a) Final Commission orders; persons aggrieved; petition; record; findings; affirmance, modification, enforcement, or setting aside of orders; remand to adduce additional evidence"],[0,"(1) A person aggrieved by a final order of the Commission entered pursuant to this chapter may obtain review of the order in the United States Court of Appeals for the circuit in which he resides or has his principal place of business, or for the District of Columbia Circuit, by filing in such court, within sixty days after the entry of the order, a written petition requesting that the order be modified or set aside in whole or in part."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated by the Commission for that purpose. Thereupon the Commission shall file in the court the record on which the order complained of is entered, as provided in section 2112 of title 28 and the Federal Rules of Appellate Procedure."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the record, to affirm or modify and enforce or to set aside the order in whole or in part."],[0,"(4) The findings of the Commission as to the facts, if supported by substantial evidence, are conclusive."],[0,"(5) If either party applies to the court for leave to adduce additional evidence and shows to the satisfaction of the court that the additional evidence is material and that there was reasonable ground for failure to adduce it before the Commission, the court may remand the case to the Commission for further proceedings, in whatever manner and on whatever conditions the court considers appropriate. If the case is remanded to the Commission, it shall file in the court a supplemental record containing any new evidence, any further or modified findings, and any new order."],[0,"(b) Commission rules; persons adversely affected; petition; record; affirmance, enforcement, or setting aside of rules; findings; transfer of proceedings"],[0,"(1) A person adversely affected by a rule of the Commission promulgated pursuant to section 78f, 78i(h)(2), 78k, 78k–1, 78o(c)(5) or (6), 78o–3, 78q, 78q–1, or 78s of this title may obtain review of this rule in the United States Court of Appeals for the circuit in which he resides or has his principal place of business or for the District of Columbia Circuit, by filing in such court, within sixty days after the promulgation of the rule, a written petition requesting that the rule be set aside."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated for that purpose. Thereupon, the Commission shall file in the court the rule under review and any documents referred to therein, the Commission's notice of proposed rulemaking and any documents referred to therein, all written submissions and the transcript of any oral presentations in the rulemaking, factual information not included in the foregoing that was considered by the Commission in the promulgation of the rule or proffered by the Commission as pertinent to the rule, the report of any advisory committee received or considered by the Commission in the rulemaking, and any other materials prescribed by the court."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the materials set forth in paragraph (2) of this subsection, to affirm and enforce or to set aside the rule."],[0,"(4) The findings of the Commission as to the facts identified by the Commission as the basis, in whole or in part, of the rule, if supported by substantial evidence, are conclusive. The court shall affirm and enforce the rule unless the Commission's action in promulgating the rule is found to be arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law; contrary to constitutional right, power, privilege, or immunity; in excess of statutory jurisdiction, authority, or limitations, or short of statutory right; or without observance of procedure required by law."],[0,"(5) If proceedings have been instituted under this subsection in two or more courts of appeals with respect to the same rule, the Commission shall file the materials set forth in paragraph (2) of this subsection in that court in which a proceeding was first instituted. The other courts shall thereupon transfer all such proceedings to the court in which the materials have been filed. For the convenience of the parties in the interest of justice that court may thereafter transfer all the proceedings to any other court of appeals."],[0,"(c) Objections not urged before Commission; stay of orders and rules; transfer of enforcement or review proceedings"],[0,"(1) No objection to an order or rule of the Commission, for which review is sought under this section, may be considered by the court unless it was urged before the Commission or there was reasonable ground for failure to do so."],[0,"(2) The filing of a petition under this section does not operate as a stay of the Commission's order or rule. Until the court's jurisdiction becomes exclusive, the Commission may stay its order or rule pending judicial review if it finds that justice so requires. After the filing of a petition under this section, the court, on whatever conditions may be required and to the extent necessary to prevent irreparable injury, may issue all necessary and appropriate process to stay the order or rule or to preserve status or rights pending its review; but (notwithstanding section 705 of title 5) no such process may be issued by the court before the filing of the record or the materials set forth in subsection (b)(2) of this section unless: (A) the Commission has denied a stay or failed to grant requested relief, (B) a reasonable period has expired since the filing of an application for a stay without a decision by the Commission, or (C) there was reasonable ground for failure to apply to the Commission."],[0,"(3) When the same order or rule is the subject of one or more petitions for review filed under this section and an action for enforcement filed in a district court of the United States under section 78u(d) or (e) of this title, that court in which the petition or the action is first filed has jurisdiction with respect to the order or rule to the exclusion of any other court, and thereupon all such proceedings shall be transferred to that court; but, for the convenience of the parties in the interest of justice, that court may thereafter transfer all the proceedings to any other court of appeals or district court of the United States, whether or not a petition for review or an action for enforcement was originally filed in the transferee court. The scope of review by a district court under section 78u(d) or (e) of this title is in all cases the same as by a court of appeals under this section."],[0,"(d) Other appropriate regulatory agencies"],[0,"(1) For purposes of the preceding subsections of this section, the term \"Commission\" includes the agencies enumerated in section 78c(a)(34) of this title insofar as such agencies are acting pursuant to this chapter and the Secretary of the Treasury insofar as he is acting pursuant to section 78o–5 of this title."],[0,"(2) For purposes of subsection (a)(4) of this section and section 706 of title 5, an order of the Commission pursuant to section 78s(a) of this title denying registration to a clearing agency for which the Commission is not the appropriate regulatory agency or pursuant to section 78s(b) of this title disapproving a proposed rule change by such a clearing agency shall be deemed to be an order of the appropriate regulatory agency for such clearing agency insofar as such order was entered by reason of a determination by such appropriate regulatory agency pursuant to section 78s(a)(2)(C) or 78s(b)(4)(C) of this title that such registration or proposed rule change would be inconsistent with the safeguarding of securities or funds."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78y?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§78y. Court review of orders and rules","tname":"Commerce and Trade","by":{"1":"40–41, 40, 41, 40","3":"18"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","subs":["(1)","(5)","(2)","(3)"],"stext":{"head":"§2342. Jurisdiction of court of appeals","paras":[[0,"The court of appeals (other than the United States Court of Appeals for the Federal Circuit) has exclusive jurisdiction to enjoin, set aside, suspend (in whole or in part), or to determine the validity of—"],[1,"(1) all final orders of the Federal Communication Commission made reviewable by section 402(a) of title 47;"],[1,"(2) all final orders of the Secretary of Agriculture made under chapters 9 and 20A of title 7, except orders issued under sections 210(e), 217a, and 499g(a) of title 7;"],[1,"(3) all rules, regulations, or final orders of—"],[2,"(A) the Secretary of Transportation issued pursuant to section 50501, 50502, 56101–56104, or 57109 of title 46 or pursuant to part B or C of subtitle IV, subchapter III of chapter 311, chapter 313, or chapter 315 of title 49; and"],[2,"(B) the Federal Maritime Commission issued pursuant to section 305,1 41304, 41308, or 41309 or chapter 421 or 441 of title 46;"],[1,"(4) all final orders of the Atomic Energy Commission made reviewable by section 2239 of title 42;"],[1,"(5) all rules, regulations, or final orders of the Surface Transportation Board made reviewable by section 2321 of this title;"],[1,"(6) all final orders under section 812 of the Fair Housing Act; and"],[1,"(7) all final agency actions described in section 20114(c) of title 49."],[0,"Jurisdiction is invoked by filing a petition as provided by section 2344 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2342?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§2342. Jurisdiction of court of appeals","tname":"Judiciary and Judicial Procedure","by":{"1":"3, 11, 14, 23, 43, 24, 25, 23","2":"21, 22, 21, 22, 21, 22, 21, 22, 21, 22"}},{"t":"usc","label":"28 U.S.C. § 2349","url":"https://www.law.cornell.edu/uscode/text/28/2349","subs":["(a)"],"stext":{"head":"§2349. Jurisdiction of the proceeding","paras":[[0,"(a) The court of appeals has jurisdiction of the proceeding on the filing and service of a petition to review. The court of appeals in which the record on review is filed, on the filing, has jurisdiction to vacate stay orders or interlocutory injunctions previously granted by any court, and has exclusive jurisdiction to make and enter, on the petition, evidence, and proceedings set forth in the record on review, a judgment determining the validity of, and enjoining, setting aside, or suspending, in whole or in part, the order of the agency."],[0,"(b) The filing of the petition to review does not of itself stay or suspend the operation of the order of the agency, but the court of appeals in its discretion may restrain or suspend, in whole or in part, the operation of the order pending the final hearing and determination of the petition. When the petitioner makes application for an interlocutory injunction restraining or suspending the enforcement, operation, or execution of, or setting aside, in whole or in part, any order reviewable under this chapter, at least 5 days' notice of the hearing thereon shall be given to the agency and to the Attorney General. In a case in which irreparable damage would otherwise result to the petitioner, the court of appeals may, on hearing, after reasonable notice to the agency and to the Attorney General, order a temporary stay or suspension, in whole or in part, of the operation of the order of the agency for not more than 60 days from the date of the order pending the hearing on the application for the interlocutory injunction, in which case the order of the court of appeals shall contain a specific finding, based on evidence submitted to the court of appeals, and identified by reference thereto, that irreparable damage would result to the petitioner and specifying the nature of the damage. The court of appeals, at the time of hearing the application for an interlocutory injunction, on a like finding, may continue the temporary stay or suspension, in whole or in part, until decision on the application."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2349?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2349. Jurisdiction of the proceeding","tname":"Judiciary and Judicial Procedure","by":{"1":"23","2":"21, 22, 10"}},{"t":"usc","label":"47 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/47/402","subs":["(a)","(b)"],"stext":{"head":"§402. Judicial review of Commission's orders and decisions","paras":[[0,"(a) Procedure"],[0,"Any proceeding to enjoin, set aside, annul, or suspend any order of the Commission under this chapter (except those appealable under subsection (b) of this section) shall be brought as provided by and in the manner prescribed in chapter 158 of title 28."],[0,"(b) Right to appeal"],[0,"Appeals may be taken from decisions and orders of the Commission to the United States Court of Appeals for the District of Columbia in any of the following cases:"],[1,"(1) By any applicant for a construction permit or station license, whose application is denied by the Commission."],[1,"(2) By any applicant for the renewal or modification of any such instrument of authorization whose application is denied by the Commission."],[1,"(3) By any party to an application for authority to transfer, assign, or dispose of any such instrument of authorization, or any rights thereunder, whose application is denied by the Commission."],[1,"(4) By any applicant for the permit required by section 325 of this title whose application has been denied by the Commission, or by any permittee under said section whose permit has been revoked by the Commission."],[1,"(5) By the holder of any construction permit or station license which has been modified or revoked by the Commission."],[1,"(6) By any other person who is aggrieved or whose interests are adversely affected by any order of the Commission granting or denying any application described in paragraphs (1), (2), (3), (4), and (9) of this subsection."],[1,"(7) By any person upon whom an order to cease and desist has been served under section 312 of this title."],[1,"(8) By any radio operator whose license has been suspended by the Commission."],[1,"(9) By any applicant for authority to provide interLATA services under section 271 of this title whose application is denied by the Commission."],[1,"(10) By any person who is aggrieved or whose interests are adversely affected by a determination made by the Commission under section 618(a)(3) of this title."],[0,"(c) Filing notice of appeal; contents; jurisdiction; temporary orders"],[0,"Such appeal shall be taken by filing a notice of appeal with the court within thirty days from the date upon which public notice is given of the decision or order complained of. Such notice of appeal shall contain a concise statement of the nature of the proceedings as to which the appeal is taken; a concise statement of the reasons on which the appellant intends to rely, separately stated and numbered; and proof of service of a true copy of said notice and statement upon the Commission. Upon filing of such notice, the court shall have jurisdiction of the proceedings and of the questions determined therein and shall have power, by order, directed to the Commission or any other party to the appeal, to grant such temporary relief as it may deem just and proper. Orders granting temporary relief may be either affirmative or negative in their scope and application so as to permit either the maintenance of the status quo in the matter in which the appeal is taken or the restoration of a position or status terminated or adversely affected by the order appealed from and shall, unless otherwise ordered by the court, be effective pending hearing and determination of said appeal and compliance by the Commission with the final judgment of the court rendered in said appeal."],[0,"(d) Notice to interested parties; filing of record"],[0,"Upon the filing of any such notice of appeal the appellant shall, not later than five days after the filing of such notice, notify each person shown by the records of the Commission to be interested in said appeal of the filing and pendency of the same. The Commission shall file with the court the record upon which the order complained of was entered, as provided in section 2112 of title 28."],[0,"(e) Intervention"],[0,"Within thirty days after the filing of any such appeal any interested person may intervene and participate in the proceedings had upon said appeal by filing with the court a notice of intention to intervene and a verified statement showing the nature of the interest of such party, together with proof of service of true copies of said notice and statement, both upon appellant and upon the Commission. Any person who would be aggrieved or whose interest would be adversely affected by a reversal or modification of the order of the Commission complained of shall be considered an interested party."],[0,"(f) Records and briefs"],[0,"The record and briefs upon which any such appeal shall be heard and determined by the court shall contain such information and material, and shall be prepared within such time and in such manner as the court may by rule prescribe."],[0,"(g) Time of hearing; procedure"],[0,"The court shall hear and determine the appeal upon the record before it in the manner prescribed by section 706 of title 5."],[0,"(h) Remand"],[0,"In the event that the court shall render a decision and enter an order reversing the order of the Commission, it shall remand the case to the Commission to carry out the judgment of the court and it shall be the duty of the Commission, in the absence of the proceedings to review such judgment, to forthwith give effect thereto, and unless otherwise ordered by the court, to do so upon the basis of the proceedings already had and the record upon which said appeal was heard and determined."],[0,"(i) Judgment for costs"],[0,"The court may, in its discretion, enter judgment for costs in favor of or against an appellant, or other interested parties intervening in said appeal, but not against the Commission, depending upon the nature of the issues involved upon said appeal and the outcome thereof."],[0,"(j) Finality of decision; review by Supreme Court"],[0,"The court's judgment shall be final, subject, however, to review by the Supreme Court of the United States upon writ of certiorari on petition therefor under section 1254 of title 28, by the appellant, by the Commission, or by any interested party intervening in the appeal, or by certification by the court pursuant to the provisions of that section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/402?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§402. Judicial review of Commission's orders and decisions","tname":"Telecommunications","by":{"1":"23–24","2":"2, 2"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"1":"2"}},{"t":"reg","label":"47 C.F.R. § 64.1200","url":"https://www.ecfr.gov/current/title-47/section-64.1200","subs":["(a)(4)","(a)(4)(iv)"],"by":{"1":"46, 1, 19, 28"}},{"t":"case","label":"B. F. Goodrich Co. v. Northwest Indus., Inc.","cite":"424 F.2d 1349","y":1970,"url":"https://www.courtlistener.com/c/F.2d/424/1349/","by":{"2":"17"}},{"t":"case","label":"(III) Cases—Continued: Biggerstaff v. FCC","cite":"511 F.3d 178","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/511/178/","by":{"2":"5","3":"14"}},{"t":"case","label":"Bowles v. Willingham","cite":"321 U.S. 503","y":1944,"id":"scdb/1943-042","sc":1,"op":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942 and § 24 (1) of the Judicial Code, and in view of § 204 (d) of the Act, a federal district court in a suit by the Administrator has authority to enjoin a proceeding in a state court to restrain issuance by the Administrator of rent orders; and § 265 of the Judicial Code, forbidding federal courts to enjoin proceedings in state courts, is inapplicable.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Central Texas Tel. Coop., Inc. v. FCC","cite":"402 F.3d 205","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/402/205/","by":{"2":"34"}},{"t":"case","label":"City of Peoria v. General Elec. Cablevision Corp.","cite":"690 F.2d 116","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/690/116/","by":{"2":"13"}},{"t":"case","label":"Daniels v. Union Pac. R.R.","cite":"530 F.3d 936","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/530/936/","by":{"2":"13"}},{"t":"case","label":"Environmental Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"op":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Federal Crop Ins. Corp. v. Merrill","cite":"332 U.S. 380","y":1947,"id":"scdb/1947-002","sc":1,"sum":"The Corporation is not liable for the loss on the reseeded acreage.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29, 32"}},{"t":"case","label":"Jones v. Flowers","cite":"547 U.S. 220","y":2006,"id":"2005/04-1477","sc":1,"sum":"Therefore, the Court ruled that the government should have taken additional steps, such as remailing the notice or posting a notice on the house's door. Justice Thomas wrote a dissent, which was joined by Justices Scalia and Kennedy. Justice Alito took no part in the decision.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Lambert Run Coal Co. v. Baltimore & Ohio R.R.","cite":"258 U.S. 377","y":1922,"id":"scdb/1921-096","sc":1,"by":{"2":"18"}},{"t":"case","label":"Leyse v. Clear Channel Broad., Inc.","cite":"545 Fed. Appx. 444","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./545/444/","by":{"2":"13, 19"}},{"t":"case","label":"Norton v. Southern Utah Wilderness Alliance","cite":"542 U.S. 55","y":2004,"id":"2003/03-101","sc":1,"sum":"The Court ruled that the APA only allows courts to examine government agencies' failures to meet specific statutory requirements. A general complaint based on policy differences - like SUWA's view that the off- road vehicles made the Wilderness Study Areas unsuitable for preservation as wilderness - could not be heard under the APA.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Russell Motor Car Co. v. United States","cite":"261 U.S. 514","y":1923,"id":"scdb/1922-150","sc":1,"sum":"(a) The word “material” included anti-aircraft gun-mounts for the Navy.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"SBC Inc. v. FCC","cite":"414 F.3d 486","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/414/486/","by":{"2":"34"}},{"t":"case","label":"Sorenson Commc’ns, Inc. v. FCC","cite":"567 F.3d 1215","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/567/1215/","by":{"2":"34"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"sum":"The Armed Career Criminal Act’s elements clause encompasses a robbery offense that, like Florida’s law, requires the criminal to overcome the victim’s resistance.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14"}},{"t":"case","label":"US West Commc’ns, Inc. v. Hamilton","cite":"224 F.3d 1049","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/224/1049/","op":2,"by":{"2":"34","3":"21"}},{"t":"case","label":"United States v. Any & All Radio Station Transmission Equip.","cite":"207 F.3d 458","y":2000,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/207/458/","by":{"2":"13"}},{"t":"case","label":"United States v. Dunifer","cite":"219 F.3d 1004","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/219/1004/","by":{"2":"13"}},{"t":"case","label":"United States v. International Minerals & Chem. Corp.","cite":"402 U.S. 558","y":1971,"id":"1970/557","sc":1,"sum":"Appellee was charged by information with shipping sulfuric and hydrofluosilicic acids in interstate commerce and that it \"did knowingly fail to show on the shipping papers the required classification of said property, to wit, Corrosive Liquid, in violation of 49 C. F. R. 173.437,\" issued pursuant to 18 U. S. C. § 834 (a). Section 834 (f) provides that whoever \"knowingly violates any such regulation\" shall be fined …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29, 32"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"United States v. Ruzicka","cite":"329 U.S. 287","y":1946,"id":"scdb/1946-018","sc":1,"sum":"They can not assert this defense in an enforcement proceeding under § 8a (6) but are left to the administrative remedy specifically provided by § 8c (15). Stark v. Wickard, 321 U. S. 288, differentiated. Pp. 290-296. 152 F. 2d 167, reversed. In a suit by the Government under § 8a (6) of the Agricultural Marketing Agreement Act of 1937 against certain handlers of milk to enforce their obligation to make payments into …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32","3":"9"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"United States v. Szabo","cite":"760 F.3d 997","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/760/997/","by":{"2":"26","3":"15"}},{"t":"case","label":"Venner v. Michigan Cent. R.R.","cite":"271 U.S. 127","y":1926,"id":"scdb/1925-189","sc":1,"by":{"2":"9, 17, 21, 23, 30","3":"9"}},{"t":"case","label":"WWHT, Inc. v. FCC","cite":"656 F.2d 807","y":1981,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/656/807/","by":{"2":"28"}},{"t":"case","label":"Water Transp. Ass’n v. ICC","cite":"819 F.2d 1189","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1189/","op":10,"ar":1,"by":{"2":"26"}},{"t":"case","label":"Woods v. Hills","cite":"334 U.S. 210","y":1948,"id":"scdb/1947-080","sc":1,"sum":"Under § 205 of the Emergency Price Control Act, the Administrator brought anaction based on an alleged overcharge of rent. The issue, by stipulation of the parties, was the validity of the second of two orders of the Rent Director reducing maximum rents on property of the defendant. The District Court entered judgment for the defendant in 1946. An appeal by the Administrator was not submitted in the Circuit Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8, 14","3":"6"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"13, 25"}},{"t":"usc","label":"28 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/28/2344","stext":{"head":"§2344. Review of orders; time; notice; contents of petition; service","paras":[[0,"On the entry of a final order reviewable under this chapter, the agency shall promptly give notice thereof by service or publication in accordance with its rules. Any party aggrieved by the final order may, within 60 days after its entry, file a petition to review the order in the court of appeals wherein venue lies. The action shall be against the United States. The petition shall contain a concise statement of—"],[1,"(1) the nature of the proceedings as to which review is sought;"],[1,"(2) the facts on which venue is based;"],[1,"(3) the grounds on which relief is sought; and"],[1,"(4) the relief prayed."],[0,"The petitioner shall attach to the petition, as exhibits, copies of the order, report, or decision of the agency. The clerk shall serve a true copy of the petition on the agency and on the Attorney General by registered mail, with request for a return receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2344?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2344. Review of orders; time; notice; contents of petition; service","tname":"Judiciary and Judicial Procedure","by":{"2":"21, 22"}},{"t":"usc","label":"28 U.S.C. § 2348","url":"https://www.law.cornell.edu/uscode/text/28/2348","by":{"2":"21, 22"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"2":"10"}},{"t":"usc","label":"47 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/47/151","by":{"2":"17"}},{"t":"usc","label":"47 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/47/405","by":{"2":"26"}},{"t":"usc","label":"47 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/47/501","by":{"2":"3"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)"],"by":{"2":"2"}},{"t":"usc","label":"28 U.S.C. § 46","url":"https://www.law.cornell.edu/uscode/text/28/46","subs":["(1934)"],"by":{"2":"17, 22"}},{"t":"usc","label":"28 U.S.C. § 1507","url":"https://www.law.cornell.edu/uscode/text/28/1507","by":{"2":"29"}},{"t":"usc","label":"28 U.S.C. § 2112","url":"https://www.law.cornell.edu/uscode/text/28/2112","subs":["(a)(3)"],"by":{"2":"2"}},{"t":"usc","label":"44 U.S.C. § 1507","url":"https://www.law.cornell.edu/uscode/text/44/1507","by":{"2":"29"}},{"t":"usc","label":"50 U.S.C. § 167h","url":"https://www.law.cornell.edu/uscode/text/50/167h","subs":["(b)"],"by":{"2":"2"}},{"t":"reg","label":"68 Fed. Reg. 53,740","url":"https://www.govinfo.gov/link/fr/68/53740","by":{"2":"5"}},{"t":"case","label":"Bradley v. City of Richmond","cite":"227 U.S. 477","y":1913,"id":"scdb/1912-115","sc":1,"op":1,"sum":"1913.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"13, 14"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"City of Bos. Delegation v. Fed. Energy Regulatory Comm’n","cite":"897 F.3d 241","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/897/241/","by":{"3":"14"}},{"t":"case","label":"Direct Mktg. Ass’n v. Brohl","cite":"135 S. Ct. 1124","y":2015,"id":"2014/13-1032","sc":1,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Gen. Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"135 S. Ct. 1199","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1199/","sc":1,"op":3,"by":{"3":"21"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19, 20"}},{"t":"usc","label":"28 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/28/1341","by":{"3":"5"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(b)(2)"],"stext":{"head":"§7607. Administrative proceedings and judicial review","paras":[[0,"(a) Administrative subpenas; confidentiality; witnesses"],[0,"In connection with any determination under section 7410(f) of this title, or for purposes of obtaining information under section 7521(b)(4) 1 or 7545(c)(3) of this title, any investigation, monitoring, reporting requirement, entry, compliance inspection, or administrative enforcement proceeding under the 2 chapter (including but not limited to section 7413, section 7414, section 7420, section 7429, section 7477, section 7524, section 7525, section 7542, section 7603, or section 7606 of this title),,3 the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for emission data, upon a showing satisfactory to the Administrator by such owner or operator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes of such owner or operator, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, to persons carrying out the National Academy of Sciences' study and investigation provided for in section 7521(c) of this title, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subparagraph,4 the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(b) Judicial review"],[0,"(1) A petition for review of action of the Administrator in promulgating any national primary or secondary ambient air quality standard, any emission standard or requirement under section 7412 of this title, any standard of performance or requirement under section 7411 of this title,,3 any standard under section 7521 of this title (other than a standard required to be prescribed under section 7521(b)(1) of this title), any determination under section 7521(b)(5) 1 of this title, any control or prohibition under section 7545 of this title, any standard under section 7571 of this title, any rule issued under section 7413, 7419, or under section 7420 of this title, or any other nationally applicable regulations promulgated, or final action taken, by the Administrator under this chapter may be filed only in the United States Court of Appeals for the District of Columbia. A petition for review of the Administrator's action in approving or promulgating any implementation plan under section 7410 of this title or section 7411(d) of this title, any order under section 7411(j) of this title, under section 7412 of this title, under section 7419 of this title, or under section 7420 of this title, or his action under section 1857c–10(c)(2)(A), (B), or (C) of this title (as in effect before August 7, 1977) or under regulations thereunder, or revising regulations for enhanced monitoring and compliance certification programs under section 7414(a)(3) of this title, or any other final action of the Administrator under this chapter (including any denial or disapproval by the Administrator under subchapter I) which is locally or regionally applicable may be filed only in the United States Court of Appeals for the appropriate circuit. Notwithstanding the preceding sentence a petition for review of any action referred to in such sentence may be filed only in the United States Court of Appeals for the District of Columbia if such action is based on a determination of nationwide scope or effect and if in taking such action the Administrator finds and publishes that such action is based on such a determination. Any petition for review under this subsection shall be filed within sixty days from the date notice of such promulgation, approval, or action appears in the Federal Register, except that if such petition is based solely on grounds arising after such sixtieth day, then any petition for review under this subsection shall be filed within sixty days after such grounds arise. The filing of a petition for reconsideration by the Administrator of any otherwise final rule or action shall not affect the finality of such rule or action for purposes of judicial review nor extend the time within which a petition for judicial review of such rule or action under this section may be filed, and shall not postpone the effectiveness of such rule or action."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) shall not be subject to judicial review in civil or criminal proceedings for enforcement. Where a final decision by the Administrator defers performance of any nondiscretionary statutory action to a later time, any person may challenge the deferral pursuant to paragraph (1)."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as to 5 the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."],[0,"(d) Rulemaking"],[0,"(1) This subsection applies to—"],[1,"(A) the promulgation or revision of any national ambient air quality standard under section 7409 of this title,"],[1,"(B) the promulgation or revision of an implementation plan by the Administrator under section 7410(c) of this title,"],[1,"(C) the promulgation or revision of any standard of performance under section 7411 of this title, or emission standard or limitation under section 7412(d) of this title, any standard under section 7412(f) of this title, or any regulation under section 7412(g)(1)(D) and (F) 6 of this title, or any regulation under section 7412(m) or (n) of this title,"],[1,"(D) the promulgation of any requirement for solid waste combustion under section 7429 of this title,"],[1,"(E) the promulgation or revision of any regulation pertaining to any fuel or fuel additive under section 7545 of this title,"],[1,"(F) the promulgation or revision of any aircraft emission standard under section 7571 of this title,"],[1,"(G) the promulgation or revision of any regulation under subchapter IV–A (relating to control of acid deposition),"],[1,"(H) promulgation or revision of regulations pertaining to primary nonferrous smelter orders under section 7419 of this title (but not including the granting or denying of any such order),"],[1,"(I) promulgation or revision of regulations under subchapter VI (relating to stratosphere and ozone protection),"],[1,"(J) promulgation or revision of regulations under part C of subchapter I (relating to prevention of significant deterioration of air quality and protection of visibility),"],[1,"(K) promulgation or revision of regulations under section 7521 of this title and test procedures for new motor vehicles or engines under section 7525 of this title, and the revision of a standard under section 7521(a)(3) of this title,"],[1,"(L) promulgation or revision of regulations for noncompliance penalties under section 7420 of this title,"],[1,"(M) promulgation or revision of any regulations promulgated under section 7541 of this title (relating to warranties and compliance by vehicles in actual use),"],[1,"(N) action of the Administrator under section 7426 of this title (relating to interstate pollution abatement),"],[1,"(O) the promulgation or revision of any regulation pertaining to consumer and commercial products under section 7511b(e) of this title,"],[1,"(P) the promulgation or revision of any regulation pertaining to field citations under section 7413(d)(3) of this title,"],[1,"(Q) the promulgation or revision of any regulation pertaining to urban buses or the clean-fuel vehicle, clean-fuel fleet, and clean fuel programs under part C of subchapter II,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7607?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7607. Administrative proceedings and judicial review","tname":"The Public Health and Welfare","by":{"3":"10"}},{"t":"reg","label":"and Regulations Implementing the Telephone Consumer Protection Act of 1991, 70 Fed. Reg. 75,070","url":"https://www.govinfo.gov/link/fr/70/75070","by":{"3":"14"}}]};